mapper.select:
SELECT COUNT(*)
FROM sys_user
WHERE phonenumber = #{phone}
  AND del_flag = '0'

    AND user_id <> #{excludeUserId}

SELECT FROM user_notification_receiver r JOIN user_notification n ON n.id = r.notification_id WHERE r.user_id = #{userId} AND r.deleted_flag = 0
AND n.type = #{type}
ORDER BY n.create_time DESC, n.id DESC

mapper.update:
UPDATE user_notification_receiver
SET read_at = #{now}, update_time = #{now}
WHERE user_id = #{userId}
  AND notification_id = #{messageId}
  AND deleted_flag = 0
  AND read_at IS NULL

UPDATE user_notification_receiver
SET read_at = #{now}, update_time = #{now}
WHERE user_id = #{userId}
  AND deleted_flag = 0
  AND read_at IS NULL

mapper.delete:
DELETE FROM user_notification_preference
WHERE user_id = #{userId}
  AND channel = #{channel}
  AND type = #{type}

mapper.select:
SELECT f.id AS feedback_id, f.category, f.content, f.status, f.reply, f.create_time AS submitted_at, f.handled_at FROM user_feedback f WHERE f.user_id = #{userId}
AND f.status = #{status}
ORDER BY f.create_time DESC, f.id DESC
